            revisions.append("workspace")  # Include "workspace" by default
        else:
            revisions.append("workspace")
    return revisions

def diff(repo, *args, revs=None, **kwargs):
    return repo.plots.show(
        *args, revs=_revisions(revs, repo.scm.is_dirty()), **kwargs
    )
